document.addEventListener('DOMContentLoaded',function(){const tabsContainer=document.getElementById('tabs-container');if(!tabsContainer)return;let ndx=crossfilter([]);let all=ndx.groupAll();const dateDimension=ndx.dimension(d=>d.date);const sectorDimension=ndx.dimension(d=>d.dimension_type==='sector'?d.dimension_value:null);const programDimension=ndx.dimension(d=>d.dimension_type==='program'?d.dimension_value:null);const deliveryDimension=ndx.dimension(d=>d.dimension_type==='delivery_type'?d.dimension_value:null);const fspDimension=ndx.dimension(d=>d.dimension_type==='financial_service_provider'?d.dimension_value:null);const statusDimension=ndx.dimension(d=>d.dimension_type==='status'?d.dimension_value:null);const currencyDimension=ndx.dimension(d=>d.dimension_type==='currency'?d.dimension_value:null);const countryDimension=ndx.dimension(d=>d.country_slug);const adminDimension=ndx.dimension(d=>d.dimension_type==='admin_area'?d.dimension_value:null);const regionDimension=ndx.dimension(d=>d.dimension_type==='region'?d.dimension_value:null);const primaryDimFilter=d=>d.dimension_type==='sector';const moveMonths=dateDimension.group(d3.timeMonth);const volumeByMonthGroup=moveMonths.reduceSum(d=>primaryDimFilter(d)?d.total_usd:0);const sectorGroup=sectorDimension.group().reduceSum(d=>d.dimension_type==='sector'?d.total_usd:0);const programGroup=programDimension.group().reduceSum(d=>d.dimension_type==='program'?d.total_usd:0);const deliveryGroup=deliveryDimension.group().reduceSum(d=>d.dimension_type==='delivery_type'?d.total_usd:0);const fspGroup=fspDimension.group().reduceSum(d=>d.dimension_type==='financial_service_provider'?d.total_usd:0);const statusGroup=statusDimension.group().reduceSum(d=>d.dimension_type==='status'?d.total_usd:0);const currencyGroup=currencyDimension.group().reduceSum(d=>d.dimension_type==='currency'?d.total_usd:0);const countryGroup=countryDimension.group().reduceSum(d=>primaryDimFilter(d)?d.total_usd:0);const adminGroup=adminDimension.group().reduceSum(d=>d.dimension_type==='admin_area'?d.total_usd:0);const regionGroup=regionDimension.group().reduceSum(d=>d.dimension_type==='region'?d.total_usd:0);const focusChart=dc.lineChart('#time-focus-chart');const rangeChart=dc.barChart('#time-range-chart');const sectorChart=dc.rowChart('#sector-chart');const programChart=dc.rowChart('#program-chart');const deliveryChart=dc.rowChart('#delivery-chart');const fspChart=dc.rowChart('#fsp-chart');const statusChart=dc.rowChart('#status-chart');const currencyChart=dc.rowChart('#currency-chart');const countryChart=dc.rowChart('#country-chart');const adminChart=dc.rowChart('#admin-chart');const regionChart=dc.rowChart('#region-chart');const initialYear=new Date().getFullYear();const initialDomain=[new Date(initialYear,0,1),new Date(initialYear,11,31)];focusChart.width(null).height(300).margins({top:10,right:50,bottom:30,left:60}).dimension(dateDimension).group(volumeByMonthGroup).transitionDuration(500).x(d3.scaleTime().domain(initialDomain)).round(d3.timeMonth.round).xUnits(d3.timeMonths).elasticY(true).renderHorizontalGridLines(true).rangeChart(rangeChart).brushOn(false).renderArea(true).on('filtered',updateTotals);rangeChart.width(null).height(80).margins({top:0,right:50,bottom:20,left:60}).dimension(dateDimension).group(volumeByMonthGroup).centerBar(true).gap(1).x(d3.scaleTime().domain(initialDomain)).round(d3.timeMonth.round).xUnits(d3.timeMonths).yAxis().ticks(0);sectorChart.width(null).height(300).margins({top:10,right:10,bottom:30,left:10}).dimension(sectorDimension).group(sectorGroup).elasticX(true).data(group=>group.all().filter(d=>d.key!==null&&d.value>0)).on('filtered',updateTotals);countryChart.width(null).height(300).margins({top:10,right:10,bottom:30,left:10}).dimension(countryDimension).group(countryGroup).elasticX(true).data(group=>group.top(10)).on('filtered',updateTotals);adminChart.width(null).height(300).margins({top:10,right:10,bottom:30,left:10}).dimension(adminDimension).group(adminGroup).elasticX(true).data(group=>group.all().filter(d=>d.key!==null&&d.value>0).slice(0,10)).on('filtered',updateTotals);programChart.width(null).height(300).margins({top:10,right:10,bottom:30,left:10}).dimension(programDimension).group(programGroup).elasticX(true).data(group=>group.all().filter(d=>d.key!==null&&d.value>0)).on('filtered',updateTotals);deliveryChart.width(null).height(300).margins({top:10,right:10,bottom:30,left:10}).dimension(deliveryDimension).group(deliveryGroup).elasticX(true).data(group=>group.all().filter(d=>d.key!==null&&d.value>0)).on('filtered',updateTotals);fspChart.width(null).height(300).margins({top:10,right:10,bottom:30,left:10}).dimension(fspDimension).group(fspGroup).elasticX(true).data(group=>group.all().filter(d=>d.key!==null&&d.value>0)).on('filtered',updateTotals);statusChart.width(null).height(300).margins({top:10,right:10,bottom:30,left:10}).dimension(statusDimension).group(statusGroup).elasticX(true).data(group=>group.all().filter(d=>d.key!==null&&d.value>0)).on('filtered',updateTotals);currencyChart.width(null).height(300).margins({top:10,right:10,bottom:30,left:10}).dimension(currencyDimension).group(currencyGroup).elasticX(true).data(group=>group.all().filter(d=>d.key!==null&&d.value>0)).on('filtered',updateTotals);regionChart.width(null).height(300).margins({top:10,right:10,bottom:30,left:10}).dimension(regionDimension).group(regionGroup).elasticX(true).data(group=>group.all().filter(d=>d.key!==null&&d.value>0).slice(0,10)).on('filtered',updateTotals);function updateTotals(){const totalUsd=ndx.groupAll().reduceSum(d=>primaryDimFilter(d)?d.total_usd:0).value();const totalPayments=ndx.groupAll().reduceSum(d=>primaryDimFilter(d)?d.payment_count:0).value();document.getElementById('total-disbursed').textContent='$'+d3.format(',.2f')(totalUsd);document.getElementById('total-payments').textContent=d3.format(',')(totalPayments);}
async function loadData(year,isInitial=false){try{const url=`${window.DASHBOARD_CONFIG.endpoint}?year=${year}&dashboard=${window.DASHBOARD_CONFIG.type}`;const response=await fetch(url,{credentials:'same-origin',headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});if(!response.ok){if(response.status===403){console.error('Authentication required. Please log in.');return;}
throw new Error(`HTTP error!status:${response.status}`);}
const data=await response.json();const dateFormat=d3.timeParse('%Y-%m-%d');data.forEach(d=>{d.date=dateFormat(d.date);d.total_usd=+d.total_usd;d.payment_count=+d.payment_count;});ndx.remove();ndx.add(data);const yearDomain=[new Date(year,0,1),new Date(year,11,31)];focusChart.x(d3.scaleTime().domain(yearDomain));rangeChart.x(d3.scaleTime().domain(yearDomain));if(isInitial){dc.renderAll();}else{dc.redrawAll();}
updateTotals();}catch(error){console.error('Error loading dashboard data:',error);}}
tabsContainer.querySelectorAll('.year-tab').forEach(btn=>{btn.addEventListener('click',function(){tabsContainer.querySelectorAll('.year-tab').forEach(b=>b.classList.remove('bg-white','shadow','text-blue-600','active-tab'));this.classList.add('bg-white','shadow','text-blue-600','active-tab');loadData(this.dataset.year);});});const firstYear=tabsContainer.querySelector('.active-tab')?.dataset.year;if(firstYear){loadData(firstYear,true);}
window.addEventListener('resize',function(){focusChart.rescale();rangeChart.rescale();dc.renderAll();});});